      SUBROUTINE MENTERCC     KNOWN MISALIGNMENT AT SECTION ENTRANCECC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM7B.CIN'      INCLUDE 'ELM8A.CIN'      INCLUDE 'ELM8D.CIN'      INCLUDE 'ELM8K.CIN'      INCLUDE 'ELM10E.CIN'      INCLUDE 'ELM13B.CIN'      INCLUDE 'R.CIN'CC     LOCAL VARIABLESC      REAL  VDIS1(3), VROT1(3)      EQUIVALENCE  (RX,VROT(1)), (RY,VROT(2)), (RZ,VROT(3))CC------------------------------------------------------------------      CALL MVTODRC      DO 20 J = 1, 3      SD = 0.0      SR = 0.0      DO 18 K = 1, 3      SD = SD + OT(J,K)*VDIS(K)      SR = SR + OT(J,K)*VROT(K)   18 CONTINUE      VDIS1(J) = SD      VROT1(J) = SR   20 CONTINUEC      DO 30 J = 1, 3      VDIS(J) = VDIS1(J)   30 VROT(J) = VROT1(J)CC     ROTATION MATRIX FOR MAGNETC      CALL MROTC      DO 40 J = 1, 3      SS = 0.0      DO 35 K = 1, 3      SS = SS + RM(J,K)*XT(K)   35 CONTINUE      VDIS(J) = VDIS(J) + SS   40 CONTINUECC     TRANSPOSE ROTATION MATRIX TO ACT ON COORDINATESC      DO 50 J = 2, 3      JM1 = J - 1      DO 50 K = 1, JM1      S = RM(J,K)      RM(J,K) = RM(K,J)      RM(K,J) = S   50 CONTINUEC      CALL MMTXC      IF (FEO) GO TO 70      DO 60 J = 1, 3      SS = 0.0      DO 55 K = 1, 3      SS = SS + RM(J,K)*VDIS(K)   55 CONTINUE      RMV(J) = SS   60 CONTINUEC      COD(1) = - RMV(1) + MM(1,3)*RMV(3)      COD(2) = RM(1,3)/RM(3,3)      COD(3) = - RMV(2) + MM(2,3)*RMV(3)      COD(4) = RM(2,3)/RM(3,3)      COD(5) = - RMV(3)      DCOV = .TRUE.      IF (BAX) R1P = .TRUE.C   70 R(1,1) = RM(1,1) - MM(1,3)*RM(3,1)      R(1,2) = MM(1,1)*RMV(3)      R(1,3) = RM(1,2) - MM(1,3)*RM(3,2)      R(1,4) = MM(1,2)*RMV(3)      R(2,2) = MM(1,1)      R(2,4) = MM(1,2)      R(3,1) = RM(2,1) - MM(2,3)*RM(3,1)      R(3,2) = MM(2,1)*RMV(3)      R(3,3) = RM(2,2) - MM(2,3)*RM(3,2)      R(3,4) = MM(2,2)*RMV(3)      R(4,2) = MM(2,1)      R(4,4) = MM(2,2)C      RETURN      END